# ============================================================
# EXCEPTION HANDLING
# ============================================================
# WHAT: Mechanism to handle runtime errors gracefully.
# WHY:  Prevent crashes, provide meaningful feedback, clean up resources.

# --- Basic try/except/else/finally ---
try:
    result = 10 / 0
except ZeroDivisionError as e:
    print(f"Error: {e}")
except (TypeError, ValueError) as e:
    print(f"Type/Value Error: {e}")
except Exception as e:
    print(f"Unexpected: {e}")  # Catch-all (use sparingly!)
else:
    print("Success — no exceptions!")  # Runs ONLY if no exception
finally:
    print("Always runs — cleanup here")  # ALWAYS runs

# --- Custom Exceptions ---
class AppError(Exception):
    """Base exception for our application."""
    def __init__(self, message: str, code: int = 500):
        self.message = message
        self.code = code
        super().__init__(self.message)

class NotFoundError(AppError):
    def __init__(self, resource: str, resource_id: str):
        super().__init__(
            message=f"{resource} with id '{resource_id}' not found",
            code=404
        )

class ValidationError(AppError):
    def __init__(self, field: str, reason: str):
        self.field = field
        self.reason = reason
        super().__init__(message=f"Validation failed for '{field}': {reason}", code=400)

# Usage
def get_user(user_id: str):
    raise NotFoundError("User", user_id)

try:
    get_user("123")
except NotFoundError as e:
    print(f"[{e.code}] {e.message}")

# --- Exception Chaining ---
try:
    try:
        int("not_a_number")
    except ValueError as original:
        raise RuntimeError("Failed to parse config") from original
except RuntimeError as e:
    print(f"Error: {e}")
    print(f"Caused by: {e.__cause__}")  # Original ValueError

# --- Suppress exceptions ---
from contextlib import suppress

with suppress(FileNotFoundError):
    open("nonexistent.txt")  # Silently ignored
# Equivalent to try/except/pass but cleaner

# --- Exception Groups (Python 3.11+) ---
# Handle multiple exceptions raised simultaneously
def validate_all(data):
    errors = []
    if not data.get("name"):
        errors.append(ValueError("name is required"))
    if not data.get("email"):
        errors.append(ValueError("email is required"))
    if errors:
        raise ExceptionGroup("Validation failed", errors)

try:
    validate_all({})
except* ValueError as eg:  # except* for ExceptionGroup
    for e in eg.exceptions:
        print(f"  - {e}")

# --- Warnings (not exceptions, but related) ---
import warnings

def deprecated_function():
    warnings.warn("This function is deprecated", DeprecationWarning, stacklevel=2)
    return "old result"
